#!/bin/bash
D="/Users/pragadees.xd/Downloads/Ducky Land/concepts/themes/centre-variations/gen"
CODEX=$(find /Applications/ChatGPT.app/Contents/Resources -maxdepth 4 -name codex -type f -perm -u+x 2>/dev/null | head -1)
id="$1"; ref="$2"; desc="$3"
P="home-props-ref.png shows the EXACT art style of our game Ducky Land: flat vector cartoon game props, clean flat colour fills, ONE darker shade band on the lower-right side and ONE soft cream highlight stripe on the upper-left, uniform dark green-black ink outlines (#39452F) about 4px thick on every shape, no gradients, no texture, no noise, no drop shadow, no glow. Palette: grass #89C332, leaf #4AA539, deep leaf #2B7A37, sand #FDE48C, stone #F3E3B5, wood #C88941, dark wood #885931, cream #FFF0C7, coral #F16E4B, sun #FFB937, water #6EC9DE, pink #F4A3C0, deep pink #E07AA0, brass #E9B23A. $ref is the approved concept crop for the subject. Draw, in the home-props-ref style (NOT the concept's softer style), seen from the same high 3/4 top-down oblique game camera (we look down at about 50 degrees, so round bases are wide ovals): $desc Show the single object alone, centred, isolated on a PLAIN PURE WHITE background, no ground, no grass, no paving, no shadow on the ground, no text, no letters, no Duckies, no people other than what is asked, nothing touching the image edges, generous white margin."
"$CODEX" exec -C "$D" -s workspace-write --skip-git-repo-check -c model_reasoning_effort=high -i "$D/home-props-ref.png" -i "$D/$ref" -- "Use the imagegen skill, built-in image_gen tool, with home-props-ref.png as the style reference and $ref as the subject reference. Generate ONE image. $P Save it in the current working directory as $id.png. Reply with only the absolute path." < /dev/null > "$D/log-$id.txt" 2>&1
[ -f "$D/$id.png" ] || { f=$(ls -t ~/.codex/generated_images/*/*.png 2>/dev/null | head -1); echo "missing $id (latest gen $f)" >> "$D/missing.txt"; }
echo "done $id"
